package main

import (
	"fmt"
	"strconv"
	"strings"
)

func everyOther(items []int) []int {
	result := []int{}
	for i := 0; i < len(items); i += 2 {
		result = append(result, items[i])
	}
	return result
}

func main() {
	var n int
	fmt.Scan(&n)
	items := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&items[i])
	}
	result := everyOther(items)
	parts := make([]string, len(result))
	for i, x := range result {
		parts[i] = strconv.Itoa(x)
	}
	fmt.Println(strings.Join(parts, " "))
}
